import random
from dataclasses import dataclass, field
from typing import List, Dict


@dataclass
class Track:
    id: str
    artist: str
    skip_count: int = 0


DEFAULT_COOLDOWN = 6
MIN_ARTIST_GAP = 3
FAVORED_PICK_CHANCE = 0.75


def _on_cooldown(track: Track, history: List[str], cooldown: int) -> bool:
    return track.id in history[:cooldown]


def _artist_gap_ok(track: Track, position: int, last_artist_slot: Dict[str, int], min_gap: int) -> bool:
    last_slot = last_artist_slot.get(track.artist, -min_gap)
    return position - last_slot >= min_gap


def _split_by_affinity(tracks: List[Track]):
    if not tracks:
        return [], []
    avg_skips = sum(t.skip_count for t in tracks) / len(tracks)
    favored = [t for t in tracks if t.skip_count > avg_skips]
    overflow = [t for t in tracks if t.skip_count <= avg_skips]
    return favored, overflow


def build_shuffle_queue(tracks: List[Track], history: List[str], length: int,
                        cooldown: int = DEFAULT_COOLDOWN, min_gap: int = MIN_ARTIST_GAP) -> List[str]:
    queue = []
    last_artist_slot: Dict[str, int] = {}
    remaining = list(tracks)
    history = list(history)

    for position in range(length):
        if not remaining:
            remaining = list(tracks)

        eligible = [
            t for t in remaining
            if not _on_cooldown(t, history, cooldown)
            and _artist_gap_ok(t, position, last_artist_slot, min_gap)
        ]
        if not eligible:
            eligible = [t for t in remaining if _artist_gap_ok(t, position, last_artist_slot, min_gap)]
        if not eligible:
            eligible = list(remaining)

        favored, overflow = _split_by_affinity(eligible)
        if favored and random.random() < FAVORED_PICK_CHANCE:
            pool = favored
        else:
            pool = overflow or eligible

        choice = random.choice(pool)
        queue.append(choice.id)
        last_artist_slot[choice.artist] = position
        remaining.remove(choice)
        history.insert(0, choice.id)

    return queue
